fn swap_first_and_last(a: &Vec<i32>) -> Vec<i32> {
    let n = a.len();
    // Problem states n > 0, but handle n == 1 naturally.
    if n <= 1 {
        return a.clone();
    }

    let mut result = a.clone();
    result.swap(0, n - 1);
    result
}